#!/usr/bin/env bash
# FULL RUN: 3 epochs, 61 scans (10,819 eps / 435,468 steps), K=2 stride 8.
#
#   batch 4 is the hard ceiling: 13.04 GB peak of 16 GB; batch 6 OOMs.
#   3 epochs = 326,601 steps @ 1.74 it/s = ~52 h.
#
# Checkpoints every 20,000 steps (~3.2 h) so the run is stoppable at any point.
# NOTE: the cosine LR is scheduled for the FULL 326,601 steps, so an early stop
# leaves the LR un-annealed -- an intermediate checkpoint is a usable model but
# not a finished one.
#
# Do NOT edit this file while it runs: `sed -i` writes a new inode and the
# running bash keeps executing the old one. That silently trained the wrong
# stride for 7 hours once.
PY=/home/kneepolean/miniconda3/envs/latentpilot/bin/python
cd /home/kneepolean/shubhj/latentpilot || exit 1
export PYTHONPATH="" HF_HUB_OFFLINE=1

STEPS=326601
echo "######## FULL 3-EPOCH train started $(date) ########"
echo "  61 scans / 10,819 episodes / 435,468 steps"
echo "  K=2 stride=8 (spans 16 steps), batch 4, $STEPS steps = 3.00 epochs"
$PY -u src/train/train_pointing.py --steps $STEPS --batch-size 4 \
    --history-frames 2 --history-stride 8 \
    --save-every 20000 --log-every 200 \
    --out checkpoints/pointing_full3 2>&1 \
  | grep --line-buffered -v "it/s\]\|tied weights\|Loading weights"
echo "######## FULL 3-EPOCH train finished $(date) ########"

for mode in "--strict" ""; do
  echo "######## FULL3 eval n=150 ${mode:-diagnostic} ########"
  $PY -u scripts/eval_pointing.py --checkpoint checkpoints/pointing_full3/final \
      --split val_unseen --limit 150 --stop-threshold 0.05 $mode 2>&1 \
    | grep -v "Loading weights\|tied weights"
done
echo "######## FULL3 COMPLETE $(date) ########"
